func lookupCode2Special(b0, b1 byte) *Country {
	switch uint16(b0)<<8 | uint16(b1) {
	case 0x2a2a: // "**"
		return &countries[0]
	case 0x4131: // "A1"
		return &countries[1]
	case 0x4132: // "A2"
		return &countries[2]
	case 0x4f31: // "O1"
		return &countries[3]
	default:
		return &countries[0]
	}
}

func lookupCode3Special(b0, b1, b2 byte) *Country {
	switch uint32(b0)<<16 | uint32(b1)<<8 | uint32(b2) {
	case 0x2a2a2a: // "***"
		return &countries[0]
	case 0x414131: // "AA1"
		return &countries[1]
	default:
		return &countries[0]
	}
}
